/*
# Day-template library, exercise expansion, weekly plans, bulk import

## What this adds
- workout_day_templates: ready-made single-day blueprints (5-6 exercises,
  mostly 12-20 reps; timed holds such as stretches use seconds) covering
  cardio, HIIT, freehand, mixed, single body part (chest, back/lats,
  shoulders, quads, hamstrings/glutes, biceps, triceps, wrist/forearm,
  calves, obliques, abs), double body part, weekly 3/4/5/6-day splits,
  mobility and joint health, stretching, yoga, meditation, seniors and
  children. Staff and owner can browse and use them; only the owner edits.
- 195 exercises in total, each with form instructions and posture cues.
  No GIFs are seeded: the owner attaches their own (paste a URL, upload,
  or bulk-attach via CSV import below).
- 33 weekly and single-day PLANS created from those templates, so they
  can be assigned to a student immediately or duplicated and customised.
- est_weight: an optional free-text "estimated weight" per plan exercise
  (for example "Light" or "20 kg"), passed through to the member's app.
- admin_bulk_import_exercises: owner-only CSV import that adds new
  exercises and can attach GIF URLs to existing ones by name. This is how
  the library grows to hundreds or thousands of entries with verified
  content that the gym controls.

## Scope note
This is a curated, hand-written library, not thousands of entries.
Accuracy and safe form cues matter more than volume. Seniors and children
templates are conservative and say to supervise or check with a doctor.
*/

CREATE TABLE IF NOT EXISTS public.workout_day_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  split_family text NOT NULL,   -- e.g. 'Cardio','Freehand','Single Body Part','3-Day Split', etc.
  day_position text,            -- e.g. 'Day 1', 'Day 2' -- null for standalone days
  level text NOT NULL DEFAULT 'Beginner',  -- Beginner / Intermediate / Advanced / All levels
  description text,
  exercises jsonb NOT NULL DEFAULT '[]'::jsonb,  -- [{exercise_id,sets,reps,weight_direction,rest_seconds,notes}]
  created_by text,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.workout_day_templates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.workout_day_templates FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.admin_upsert_day_template(
  p_passcode text, p_id uuid, p_name text, p_split_family text, p_day_position text,
  p_level text, p_description text, p_exercises jsonb
)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions
AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT public.verify_owner_passcode(p_passcode) THEN RAISE EXCEPTION 'Access denied.'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by)
    VALUES (p_name, p_split_family, p_day_position, coalesce(p_level,'Beginner'), p_description, coalesce(p_exercises,'[]'::jsonb), 'owner')
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.workout_day_templates SET name=p_name, split_family=p_split_family, day_position=p_day_position,
      level=coalesce(p_level,'Beginner'), description=p_description, exercises=coalesce(p_exercises, exercises)
    WHERE id = p_id;
    v_id := p_id;
  END IF;
  RETURN v_id;
END;
$$;
GRANT EXECUTE ON FUNCTION public.admin_upsert_day_template(text,uuid,text,text,text,text,text,jsonb) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.admin_delete_day_template(p_passcode text, p_id uuid)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions
AS $$
BEGIN
  IF NOT public.verify_owner_passcode(p_passcode) THEN RAISE EXCEPTION 'Access denied.'; END IF;
  DELETE FROM public.workout_day_templates WHERE id = p_id;
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.admin_delete_day_template(text,uuid) TO anon, authenticated;

-- Staff (building a Basic plan) or owner can browse/use templates -- not edit them.
CREATE OR REPLACE FUNCTION public.list_day_templates(p_passcode text)
RETURNS SETOF public.workout_day_templates
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions
AS $$
BEGIN
  IF public.verify_admin_access(p_passcode) IS NULL THEN RAISE EXCEPTION 'Access denied.'; END IF;
  RETURN QUERY SELECT * FROM public.workout_day_templates ORDER BY split_family, day_position NULLS FIRST, level, name;
END;
$$;
GRANT EXECUTE ON FUNCTION public.list_day_templates(text) TO anon, authenticated;


-- Idempotency: template names are unique (case-insensitive)
CREATE UNIQUE INDEX IF NOT EXISTS workout_day_templates_name_uidx ON public.workout_day_templates (lower(name));
CREATE UNIQUE INDEX IF NOT EXISTS workout_exercises_name_uidx ON public.workout_exercises (lower(name));

-- ── Member app: pass the optional estimated weight through ─────────────
CREATE OR REPLACE FUNCTION public.warrior_get_my_workout(p_member_id text, p_passcode text)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions
AS $$
DECLARE v_member text; v_row public.members; v_result jsonb := '{}'::jsonb; v_plan record; v_tiers text[];
BEGIN
  v_member := upper(trim(p_member_id));
  IF NOT EXISTS (SELECT 1 FROM public.ghost_vault WHERE member_id = v_member AND passcode = trim(p_passcode)) THEN
    RAISE EXCEPTION 'Access denied.';
  END IF;
  SELECT * INTO v_row FROM public.members WHERE member_id = v_member;

  v_tiers := ARRAY['basic'];
  IF v_row.workout_pt_unlocked THEN v_tiers := v_tiers || 'pt'; END IF;
  IF v_row.workout_prep_unlocked THEN v_tiers := v_tiers || 'prep'; END IF;

  FOR v_plan IN
    SELECT p.id, p.name, p.tier, p.description, p.structure
    FROM public.workout_assignments a JOIN public.workout_plans p ON p.id = a.plan_id
    WHERE a.member_id = v_member AND a.active = true AND p.tier = ANY(v_tiers)
  LOOP
    v_result := v_result || jsonb_build_object(v_plan.tier, jsonb_build_object(
      'plan_id', v_plan.id, 'name', v_plan.name, 'description', v_plan.description,
      'days', (
        SELECT jsonb_agg(jsonb_build_object(
          'day_number', day->>'day_number', 'day_label', day->>'day_label',
          'exercises', (
            SELECT jsonb_agg(jsonb_build_object(
              'exercise_id', e.id, 'name', e.name, 'gif_url', e.gif_url, 'category', e.category,
              'muscle_group', e.muscle_group, 'instructions', e.instructions, 'posture_tips', e.posture_tips,
              'sets', ex->>'sets', 'reps', ex->>'reps', 'weight_direction', ex->>'weight_direction',
              'est_weight', ex->>'est_weight',
              'rest_seconds', ex->>'rest_seconds', 'notes', ex->>'notes'
            ) ORDER BY ord)
            FROM jsonb_array_elements(day->'exercises') WITH ORDINALITY AS t(ex, ord)
            JOIN public.workout_exercises e ON e.id = (ex->>'exercise_id')::uuid
          )
        ) ORDER BY dord)
        FROM jsonb_array_elements(v_plan.structure) WITH ORDINALITY AS d(day, dord)
      )
    ));
  END LOOP;

  RETURN jsonb_build_object('tiers_unlocked', to_jsonb(v_tiers), 'plans', v_result);
END;
$$;
GRANT EXECUTE ON FUNCTION public.warrior_get_my_workout(text,text) TO anon, authenticated;

-- ── Owner-only bulk import: add exercises, or attach GIFs by name ──────
CREATE OR REPLACE FUNCTION public.admin_bulk_import_exercises(p_passcode text, p_rows jsonb)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions
AS $$
DECLARE v_count integer := 0; r jsonb; v_gif text;
BEGIN
  IF NOT public.verify_owner_passcode(p_passcode) THEN RAISE EXCEPTION 'Access denied.'; END IF;
  IF jsonb_typeof(p_rows) <> 'array' THEN RAISE EXCEPTION 'Rows must be an array.'; END IF;
  IF jsonb_array_length(p_rows) > 2000 THEN RAISE EXCEPTION 'Import at most 2000 rows at a time.'; END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    IF coalesce(trim(r->>'name'), '') = '' THEN CONTINUE; END IF;
    v_gif := nullif(trim(r->>'gif_url'), '');
    IF v_gif IS NOT NULL AND v_gif !~* '^https://' THEN v_gif := NULL; END IF;
    INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, gif_url, instructions, posture_tips)
    VALUES (trim(r->>'name'), 'basic', nullif(trim(r->>'category'), ''), nullif(trim(r->>'muscle_group'), ''),
            nullif(trim(r->>'equipment'), ''), v_gif, nullif(trim(r->>'instructions'), ''), nullif(trim(r->>'posture_tips'), ''))
    ON CONFLICT (lower(name)) DO UPDATE SET
      gif_url = coalesce(EXCLUDED.gif_url, public.workout_exercises.gif_url),
      category = coalesce(EXCLUDED.category, public.workout_exercises.category),
      muscle_group = coalesce(EXCLUDED.muscle_group, public.workout_exercises.muscle_group),
      equipment = coalesce(EXCLUDED.equipment, public.workout_exercises.equipment),
      instructions = coalesce(EXCLUDED.instructions, public.workout_exercises.instructions),
      posture_tips = coalesce(EXCLUDED.posture_tips, public.workout_exercises.posture_tips);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;
GRANT EXECUTE ON FUNCTION public.admin_bulk_import_exercises(text,jsonb) TO anon, authenticated;

-- ── Helper (dropped at the end): "Name|sets|reps|rest|weight|est;..." -> jsonb ──
CREATE OR REPLACE FUNCTION public._tx_list(p_spec text)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE part text; f text[]; v_id uuid; v_out jsonb := '[]'::jsonb;
BEGIN
  FOREACH part IN ARRAY string_to_array(p_spec, ';') LOOP
    f := string_to_array(part, '|');
    SELECT id INTO v_id FROM public.workout_exercises WHERE lower(name) = lower(f[1]);
    IF v_id IS NULL THEN RAISE EXCEPTION 'Unknown exercise in template: %', f[1]; END IF;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'exercise_id', v_id, 'sets', f[2], 'reps', f[3], 'rest_seconds', f[4],
      'weight_direction', f[5], 'est_weight', coalesce(f[6], ''), 'notes', ''));
  END LOOP;
  RETURN v_out;
END;
$$;

