-- ── Exercise expansion, part 1 ──────────────────────────────────────────
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Lateral Raise', 'basic', 'Shoulders', 'Side deltoids', 'Dumbbells',
  'Standing, slight bend in the elbows, raise the dumbbells out to the sides until arms are roughly parallel to the floor, then lower slowly.',
  'Don''t swing the weight up using momentum or shrug the traps to lift it — raise from the shoulder joint only, stop at shoulder height.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Front Raise', 'basic', 'Shoulders', 'Front deltoids', 'Dumbbells',
  'Standing, raise a dumbbell in each hand straight out in front to shoulder height, then lower with control.',
  'Avoid leaning back to use momentum — keep the torso upright and the core braced.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Face Pull', 'basic', 'Shoulders', 'Rear deltoids, Upper back', 'Cable or band',
  'Pull the rope or band toward the face, splitting the hands apart at the end, elbows staying high, then return with control.',
  'Keep the elbows above wrist height throughout — dropping them turns this into a row and misses the rear-delt target.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Arnold Press', 'basic', 'Shoulders', 'Shoulders, Triceps', 'Dumbbells',
  'Start with palms facing you at shoulder height, press up while rotating the palms to face forward at the top, then reverse on the way down.',
  'Keep the rotation smooth and controlled — don''t rush it into a regular press and lose the rotational benefit.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Straight-Arm Pulldown', 'basic', 'Back', 'Lats', 'Cable machine',
  'Standing, arms straight, pull the bar down from overhead to the thighs in an arc, keeping a slight bend in the elbows, then return with control.',
  'Keep the arms nearly straight throughout — bending them turns this into a triceps exercise instead of a lat isolation move.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Superman', 'basic', 'Back', 'Lower back, Glutes', 'Bodyweight',
  'Lying face down, simultaneously raise the arms, chest, and legs off the floor, hold briefly, then lower with control.',
  'Lift to a comfortable range, not as high as possible — overextending the lower back can cause discomfort.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Glute Bridge', 'basic', 'Legs', 'Glutes, Hamstrings', 'Bodyweight',
  'Lying on the back, knees bent, feet flat, drive the hips up by squeezing the glutes until the body forms a straight line from shoulders to knees.',
  'Push through the heels, not the toes, and avoid overarching the lower back at the top — squeeze the glutes, don''t just extend the spine.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hip Thrust', 'basic', 'Legs', 'Glutes, Hamstrings', 'Barbell, bench',
  'Upper back braced against a bench, barbell over the hips, drive through the heels to lift the hips until the torso is parallel to the floor.',
  'Keep the chin tucked slightly and avoid hyperextending the lower back at the top — the movement should come from the hips, not the spine.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Step-Up', 'basic', 'Legs', 'Quads, Glutes', 'Box or bench',
  'Step one foot onto a raised box, drive through that heel to stand fully on top, then step back down with control.',
  'Avoid pushing off the bottom leg to "hop" up — the working leg on the box should do the lifting.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Calf Raise', 'basic', 'Legs', 'Calves', 'Machine or dumbbell on knees',
  'Seated, weight resting on the knees, rise onto the balls of the feet, pause, then lower slowly for a full stretch.',
  'Use a full range of motion — a deep stretch at the bottom is where most of the benefit comes from.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wrist Curl', 'basic', 'Wrist / Forearm', 'Forearm flexors', 'Dumbbell or barbell',
  'Forearms resting on a bench or thighs, palms up, curl the weight up using only the wrist, then lower with control.',
  'Keep the movement isolated to the wrist — the forearm itself should stay resting and still.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Reverse Wrist Curl', 'basic', 'Wrist / Forearm', 'Forearm extensors', 'Dumbbell or barbell',
  'Forearms resting on a bench or thighs, palms down, extend the wrist upward, then lower with control.',
  'Use a lighter weight than the regular wrist curl — the extensor muscles are smaller and fatigue faster.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Farmer''s Carry', 'basic', 'Wrist / Forearm', 'Grip, Forearms, Core', 'Dumbbells or kettlebells',
  'Hold a heavy weight in each hand, stand tall, and walk for distance or time while keeping the shoulders back and core braced.',
  'Don''t let the shoulders round forward or the weights swing — walk with short, controlled steps and a tall posture.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Side Plank', 'basic', 'Core', 'Obliques, Core', 'Bodyweight',
  'Lying on one side, prop up on the forearm with the body in a straight line, hips lifted off the floor, hold for time, then switch sides.',
  'Don''t let the hips sag toward the floor or rotate forward/backward — keep the whole body in one flat plane.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Oblique Crunch', 'basic', 'Core', 'Obliques', 'Bodyweight or light dumbbell',
  'Standing, hands behind the head, crunch sideways bringing the elbow toward the hip on one side, then repeat on the other.',
  'Move through the obliques, not by yanking with the arms on the neck — keep the motion controlled and side-to-side, not forward.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cable Woodchopper', 'basic', 'Core', 'Obliques, Core', 'Cable machine',
  'Pull the cable diagonally from high to low (or low to high) across the body while rotating through the torso, pivoting the back foot.',
  'Rotate through the hips and torso together — don''t just pull with the arms while the hips stay locked.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('High Knees', 'basic', 'Cardio', 'Legs, Core', 'Bodyweight',
  'Run in place, driving the knees up toward hip height as quickly as controlled form allows.',
  'Stay on the balls of the feet and keep the torso upright — don''t lean back to compensate for the pace.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Skater Jumps', 'basic', 'Cardio', 'Legs, Glutes', 'Bodyweight',
  'Leap sideways from one foot to the other in a skating motion, letting the trailing leg swing behind for balance.',
  'Land softly with a bent knee each time to absorb the impact, rather than landing stiff-legged.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Plank Jacks', 'basic', 'Cardio', 'Core, Shoulders, Legs', 'Bodyweight',
  'In a high plank position, jump the feet out wide and back together, keeping the hips stable throughout.',
  'Keep the hips level and braced — don''t let them rise up or sag as the feet move.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bear Crawl', 'basic', 'Full body / Cardio', 'Full body', 'Bodyweight',
  'On hands and feet with knees hovering just off the floor, crawl forward moving opposite hand and foot together, keeping the back flat.',
  'Keep the hips low and level with the shoulders — don''t let them pike up into the air.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Squat Jump', 'basic', 'Legs', 'Quads, Glutes, Calves', 'Bodyweight',
  'Perform a bodyweight squat, then explode upward into a jump, landing softly back into the squat position.',
  'Land with bent knees absorbing the impact quietly — a loud, stiff landing means too much force is going through the joints.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cat-Cow Stretch', 'basic', 'Mobility & Stretching', 'Spine, Core', 'Bodyweight',
  'On hands and knees, alternate between arching the back up toward the ceiling (cat) and dropping the belly while lifting the head (cow), moving slowly with the breath.',
  'Move through the whole spine segment by segment rather than just bending at one point — keep it slow and controlled.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('World''s Greatest Stretch', 'basic', 'Mobility & Stretching', 'Hips, Hamstrings, Thoracic spine', 'Bodyweight',
  'From a lunge position, place the opposite hand down, rotate the torso and reach the other arm up toward the ceiling, following with the eyes.',
  'Keep the back leg straight and the front knee tracking over the foot to get the full hip and thoracic rotation benefit.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hip Flexor Stretch', 'basic', 'Mobility & Stretching', 'Hip flexors', 'Bodyweight',
  'Kneeling lunge position, back knee down, gently push the hips forward until a stretch is felt at the front of the back hip.',
  'Keep the torso upright rather than leaning forward — leaning forward takes the stretch out of the hip flexor.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Shoulder Dislocates', 'basic', 'Mobility & Stretching', 'Shoulders', 'Band or stick',
  'Holding a band or stick with a wide grip, raise the arms overhead and continue the arc behind the back, then reverse, keeping the arms straight throughout.',
  'Widen the grip if the shoulders or elbows feel strained — the movement should be smooth and pain-free, never forced.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Thoracic Spine Rotation', 'basic', 'Mobility & Stretching', 'Upper back, Spine', 'Bodyweight',
  'On hands and knees, one hand behind the head, rotate the elbow down toward the opposite arm then open it up toward the ceiling, following with the eyes.',
  'Keep the hips still and let the rotation happen through the upper back only.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Ankle Mobility Drill', 'basic', 'Mobility & Stretching', 'Ankles', 'Bodyweight',
  'In a half-kneeling position, drive the front knee forward over the toes without the heel lifting, feeling a stretch in the ankle, repeat for reps.',
  'Keep the heel glued to the floor throughout — if it lifts, the movement is coming from somewhere other than the ankle.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Hamstring Stretch', 'basic', 'Mobility & Stretching', 'Hamstrings', 'Bodyweight',
  'One heel propped on a low surface, leg straight, hinge forward at the hips keeping the back flat until a stretch is felt behind the thigh.',
  'Keep the back flat rather than rounding forward to reach further — the stretch should come from the hip hinge.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Doorway Chest Stretch', 'basic', 'Mobility & Stretching', 'Chest, Front shoulders', 'Doorway',
  'Forearm against a doorframe at shoulder height, gently lean the body forward through the doorway until a stretch is felt across the chest.',
  'Keep the movement gentle and sustained rather than bouncing into the stretch.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Neck Mobility Circles', 'basic', 'Mobility & Stretching', 'Neck', 'Bodyweight',
  'Slowly and gently roll the head in a circular motion through a comfortable range, then reverse direction.',
  'Keep the movement slow and pain-free — never force the neck into an uncomfortable range.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Downward Dog', 'basic', 'Yoga & Meditation', 'Full body', 'Yoga mat',
  'From hands and knees, lift the hips up and back forming an inverted V shape, heels reaching toward the floor, head relaxed between the arms.',
  'Bend the knees slightly if the hamstrings are tight rather than rounding the lower back to get the heels down.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Child''s Pose', 'basic', 'Yoga & Meditation', 'Lower back, Hips', 'Yoga mat',
  'Kneel and sit back onto the heels, fold forward with arms extended or relaxed at the sides, forehead resting on the mat, breathing slowly.',
  'A gentle resting pose — there is no strain here; let the breath deepen the relaxation.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cobra Pose', 'basic', 'Yoga & Meditation', 'Spine, Chest', 'Yoga mat',
  'Lying face down, hands under the shoulders, gently press up lifting the chest while keeping the hips on the mat.',
  'Keep the shoulders away from the ears and don''t push up higher than is comfortable for the lower back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Warrior II Pose', 'basic', 'Yoga & Meditation', 'Legs, Hips, Core', 'Yoga mat',
  'Wide stance, front knee bent over the ankle, back leg straight, arms extended parallel to the floor, gaze over the front hand.',
  'Keep the front knee tracking over the ankle, not collapsing inward, and keep the torso upright rather than leaning over the front leg.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Sun Salutation (Surya Namaskar)', 'basic', 'Yoga & Meditation', 'Full body', 'Yoga mat',
  'A flowing sequence linking a forward fold, plank, cobra, and downward dog with the breath — one full round is typically 8-12 linked movements.',
  'Move at the pace of the breath rather than rushing — the transitions matter as much as the poses themselves.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Box Breathing', 'basic', 'Yoga & Meditation', 'Nervous system', 'None',
  'Inhale for a count of 4, hold for 4, exhale for 4, hold empty for 4, and repeat for several rounds.',
  'Keep the breath smooth and unforced — if a 4-count feels difficult, shorten it rather than straining.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Diaphragmatic Breathing', 'basic', 'Yoga & Meditation', 'Nervous system', 'None',
  'Lying or seated, one hand on the chest and one on the belly, breathe so the belly hand rises more than the chest hand, slowly and fully.',
  'Keep the shoulders relaxed and still — the breath should expand the belly, not lift the chest and shoulders.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Guided Body Scan', 'basic', 'Yoga & Meditation', 'Nervous system', 'None',
  'Lying comfortably, slowly bring attention through each part of the body in turn, from the feet to the head, noticing sensation without trying to change it.',
  'There''s no "correct" posture fault here — the only guidance is to keep the attention gentle and non-judgmental.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Chair Squat', 'basic', 'Legs', 'Quads, Glutes', 'Chair', 
  'Standing in front of a sturdy chair, lower down until the hips just touch the seat, then stand back up. A safe, controlled regression for building squat strength.',
  'Keep the movement slow and controlled — this is not a drop into the chair, it''s a controlled lowering with a light touch.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wall Push-Up', 'basic', 'Push', 'Chest, Shoulders, Triceps', 'Wall',
  'Stand facing a wall, hands on the wall at shoulder height, lower the chest toward the wall and press back, an easier regression of a floor push-up.',
  'Keep the body in a straight line from head to heels, just as in a floor push-up, only at a gentler angle.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Marching', 'basic', 'Legs', 'Hip flexors, Core', 'Chair',
  'Seated in a chair, alternately lift each knee up as if marching in place, keeping the torso tall.',
  'Sit tall rather than slouching back — good posture makes this far more effective.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Side Leg Raise', 'basic', 'Legs', 'Hip abductors, Glutes', 'Chair for balance',
  'Holding onto a chair or wall for balance, lift one leg out to the side with control, then lower, keeping the standing leg slightly bent.',
  'Keep the torso upright rather than leaning to the opposite side to help lift the leg higher.') ON CONFLICT (lower(name)) DO NOTHING;

-- ── Exercise expansion, part 2: every muscle group and style ─────────────
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dumbbell Bench Press','basic','Chest','Chest, Shoulders, Triceps','Dumbbells, bench','Lie back with a dumbbell in each hand at chest level, press up until the arms are extended over the chest, then lower with control to a comfortable deep stretch.','Keep the shoulder blades pinched back and down on the bench; angle the elbows about 45-60 degrees from the torso rather than flaring them straight out.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Incline Dumbbell Press','basic','Chest','Upper chest, Shoulders','Dumbbells, incline bench','Set the bench to about 30 degrees, press the dumbbells from shoulder level up over the upper chest, then lower slowly.','A steeper bench shifts the work to the shoulders, so stay near 30 degrees. Keep a gentle lower-back arch, not a flared rib cage.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Incline Barbell Bench Press','basic','Chest','Upper chest, Shoulders','Barbell, incline bench','On a 30-degree incline, unrack the bar, lower it to the upper chest with control and press back up over the shoulders.','Keep the wrists stacked over the elbows and never bounce the bar; use a spotter for heavy sets.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Decline Push-Up','basic','Chest','Upper chest, Shoulders','Bodyweight, bench','Feet on a bench and hands on the floor slightly wider than the shoulders; lower the chest toward the floor and press back up.','Keep the body in one straight line, do not let the hips sag, and brace the core throughout.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wide-Grip Push-Up','basic','Chest','Chest','Bodyweight','Hands set wider than shoulder-width, lower the chest between the hands and press back up.','Do not go so wide that the shoulders feel strained; keep the elbows about 45-60 degrees from the body.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dumbbell Fly','basic','Chest','Chest','Dumbbells, bench','Lie back with arms extended over the chest and a slight elbow bend; open the arms in a wide arc until you feel a chest stretch, then bring the weights back together.','Keep the elbow bend fixed; straightening or bending it turns the fly into a press. Use lighter weights than for pressing.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cable Crossover','basic','Chest','Chest','Cable machine','Stand between high pulleys, step forward, and with a slight elbow bend bring the handles down and together in front of the lower chest, then return with control.','Lean slightly forward with a stable stance and do not let the weight stack drag the shoulders back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Machine Chest Press','basic','Chest','Chest, Triceps','Chest press machine','Adjust the seat so the handles sit at mid-chest, press forward until the arms are nearly straight, then return slowly.','Keep the back flat against the pad and do not lock the elbows hard at full extension.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Pec Deck Fly','basic','Chest','Chest','Pec deck machine','Seated with the forearms or hands on the pads, bring the arms together in front of the chest, squeeze, then open slowly.','Set the seat so the handles align with mid-chest and avoid letting the shoulders roll forward.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('One-Arm Dumbbell Row','basic','Back / Lats','Lats, Upper back, Biceps','Dumbbell, bench','With one hand and knee on a bench, pull the dumbbell toward the hip with the elbow close to the body, then lower to a full stretch.','Keep the back flat and hips square; do not twist the torso to heave the weight up.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Chest-Supported Row','basic','Back / Lats','Upper back, Lats','Dumbbells or machine, incline bench','Lie chest-down on an incline bench and row the weights toward the hips, squeezing the shoulder blades, then lower slowly.','Keep the chest on the pad and avoid shrugging the shoulders toward the ears.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('T-Bar Row','basic','Back / Lats','Mid back, Lats','T-bar or landmine','Hinge forward with a flat back, pull the handle toward the lower chest, then lower with control.','Keep the spine neutral with the hips back; if the lower back rounds, reduce the load.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Inverted Row','basic','Back / Lats','Upper back, Biceps','Bar in a rack or suspension trainer','Lie under a fixed bar with the body straight, pull the chest to the bar and lower with control.','Keep the hips up so the body stays in a straight line; walk the feet closer to the bar to make it easier.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Close-Grip Lat Pulldown','basic','Back / Lats','Lats, Biceps','Cable machine','Use a narrow neutral handle, pull to the upper chest with the elbows driving down, then return slowly.','Sit tall and avoid leaning far back or swinging; the elbows lead the movement.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Assisted Pull-Up','basic','Back / Lats','Lats, Biceps','Assisted pull-up machine or band','Grip the bar slightly wider than the shoulders and pull the chest toward it with machine or band assistance, then lower fully with control.','Lower slowly, since the descent builds strength. Reduce the assistance gradually over the weeks.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Chin-Up','basic','Back / Lats','Lats, Biceps','Pull-up bar','Take an underhand shoulder-width grip, pull the chin above the bar and lower to a full hang.','Do not swing or kip; keep the core braced and the shoulders down away from the ears.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Machine Row','basic','Back / Lats','Mid back, Lats','Row machine','With the chest against the pad, pull the handles back to the ribs squeezing the shoulder blades, then extend with control.','Do not lean back to yank the weight; keep the neck relaxed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Back Extension','basic','Back / Lats','Lower back, Glutes','Back extension bench','With the hips on the pad, hinge forward with a straight spine and raise the torso until the body is in line with the legs.','Stop at a straight line; hyperextending the lower back at the top can strain it.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dumbbell Pullover','basic','Back / Lats','Lats, Chest','Dumbbell, bench','Lie across a bench holding one dumbbell overhead with both hands; lower it in an arc behind the head with slightly bent elbows, then pull it back over the chest.','Keep the rib cage down and stay within a comfortable shoulder range; do not arch the back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Barbell Overhead Press','basic','Shoulders','Shoulders, Triceps','Barbell','Start with the bar at collarbone height, press straight overhead until the arms lock out with the head moving slightly forward, then lower to the collarbones.','Squeeze the glutes and brace the core so the lower back does not arch to push the bar.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Rear Delt Fly','basic','Shoulders','Rear deltoids','Dumbbells','Hinge forward with a flat back, raise the dumbbells out to the sides with a soft elbow bend, then lower slowly.','Lead with the elbows rather than the hands and keep the neck neutral; light weights work best.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Upright Row','basic','Shoulders','Shoulders, Traps','Barbell or dumbbells','Hold the weight at the thighs and lift it along the body to about chest height with the elbows leading, then lower.','Stop at chest height and keep the grip about shoulder-width to spare the shoulder joint.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dumbbell Shrug','basic','Shoulders','Upper traps','Dumbbells','Standing with weights at the sides, lift the shoulders straight up toward the ears, pause, then lower.','Move straight up and down; do not roll the shoulders.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Pike Push-Up','basic','Shoulders','Shoulders, Triceps','Bodyweight','From a downward-dog shape with the hips high, bend the elbows to lower the head toward the floor, then press back up.','Keep the elbows tracking back at about 45 degrees, not flared wide.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Machine Shoulder Press','basic','Shoulders','Shoulders, Triceps','Shoulder press machine','Adjust the seat so the handles are at shoulder height, press overhead, and return slowly.','Keep the back against the pad and avoid over-arching.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Goblet Squat','basic','Quads','Quads, Glutes','Dumbbell or kettlebell','Hold the weight at the chest, squat down between the knees with an upright torso, then drive up through the heels.','Keep the chest tall and the elbows inside the knees; do not let the heels lift.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Front Squat','basic','Quads','Quads, Core','Barbell, rack','Rest the bar on the front shoulders with the elbows high; squat down keeping the torso upright, then stand.','If the elbows drop the bar rolls forward, so lighten the load or work on wrist and shoulder mobility.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bulgarian Split Squat','basic','Quads','Quads, Glutes','Dumbbells or bodyweight, bench','With the rear foot on a bench, lower the back knee toward the floor with the front shin near vertical, then drive up.','Keep the torso tall and the front knee tracking over the toes; take a long enough stride.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Reverse Lunge','basic','Quads','Quads, Glutes','Bodyweight or dumbbells','Step one leg back and lower until both knees are about 90 degrees, then push through the front heel to stand.','Keep the torso upright; a reverse step is gentler on the knees than a forward lunge.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Leg Extension','basic','Quads','Quads','Leg extension machine','Seated, extend the knees until the legs are straight, squeeze, then lower slowly.','Do not swing or slam into lockout; keep the back against the pad.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wall Sit','basic','Quads','Quads','Wall','With the back against a wall, slide down until the knees are about 90 degrees and hold.','Keep the knees over the ankles and press the lower back into the wall; breathe steadily.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Smith Machine Squat','basic','Quads','Quads, Glutes','Smith machine','Place the bar on the upper back with the feet slightly forward of the bar, squat to parallel and stand.','Position the feet so the knees stay behind the toes and the heels stay planted.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Jump Lunge','basic','Quads','Quads, Glutes','Bodyweight','From a lunge, jump and switch legs in the air, landing softly in a lunge on the other side.','Land softly with control and keep the front knee stable; slow down if the landings get sloppy.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Lying Leg Curl','basic','Hamstrings / Glutes','Hamstrings','Leg curl machine','Lie face-down, curl the heels toward the glutes, squeeze, then lower slowly.','Keep the hips pressed on the pad; if they lift, the weight is too heavy.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Leg Curl','basic','Hamstrings / Glutes','Hamstrings','Leg curl machine','Seated with the pad above the heels, curl the legs under the seat, then return slowly.','Control the return and avoid using body momentum.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Good Morning','basic','Hamstrings / Glutes','Hamstrings, Glutes, Lower back','Barbell or bodyweight','With the bar on the upper back and soft knees, hinge at the hips pushing them back until the torso is near parallel, then stand.','The spine stays flat throughout; use very light weight and stop if the back rounds.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Single-Leg Romanian Deadlift','basic','Hamstrings / Glutes','Hamstrings, Glutes, Balance','Dumbbell or bodyweight','Balance on one leg and hinge forward with the other leg extending back for counterbalance, then return to standing.','Keep the hips level and the standing knee soft; touch a wall lightly if balance is a limit.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Sumo Deadlift','basic','Hamstrings / Glutes','Glutes, Hamstrings, Inner thighs','Barbell','Take a wide stance with toes turned out, grip the bar inside the knees, keep the chest up and stand by driving through the floor.','Push the knees out over the toes and keep the back flat; do not jerk the bar off the floor.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Donkey Kick','basic','Hamstrings / Glutes','Glutes','Bodyweight','On hands and knees, kick one leg back and up with the knee bent, squeeze the glute, then return.','Keep the hips square and do not arch the lower back to swing the leg higher.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Fire Hydrant','basic','Hamstrings / Glutes','Glutes, Hip abductors','Bodyweight','On hands and knees, lift one knee out to the side while keeping it bent, then lower.','Keep the torso still and the hips level; the movement comes from the hip only.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Single-Leg Glute Bridge','basic','Hamstrings / Glutes','Glutes, Hamstrings','Bodyweight','Lie on the back with one foot planted and the other leg extended, drive the hips up until the body is straight, then lower.','Keep the pelvis level and do not let the hips rotate or sag.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cable Glute Kickback','basic','Hamstrings / Glutes','Glutes','Cable machine, ankle strap','Strap the ankle to a low pulley, hinge slightly forward and kick the leg straight back, squeezing the glute, then return.','Avoid arching the lower back; move from the hip, not the spine.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Sumo Squat','basic','Hamstrings / Glutes','Glutes, Inner thighs, Quads','Dumbbell or bodyweight','Take a wide stance with toes turned out, hold a weight at the chest and squat straight down, then stand.','Push the knees out in line with the toes and keep the chest tall.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hammer Curl','basic','Biceps','Biceps, Brachialis, Forearms','Dumbbells','With palms facing each other, curl the dumbbells up toward the shoulders and lower slowly.','Keep the elbows pinned at the sides and do not swing.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Barbell Curl','basic','Biceps','Biceps','Barbell or EZ-bar','Take a shoulder-width underhand grip, curl the bar to the chest, squeeze, then lower slowly.','Do not lean back; if the hips swing, reduce the weight.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Concentration Curl','basic','Biceps','Biceps','Dumbbell','Seated with the elbow braced against the inner thigh, curl the dumbbell to the shoulder and lower slowly.','Keep the upper arm still so only the forearm moves.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Incline Dumbbell Curl','basic','Biceps','Biceps (long head)','Dumbbells, incline bench','Lie back on a 45-60 degree bench with the arms hanging straight down; curl up without moving the upper arms.','Keep the shoulders back on the pad and start light, since the stretch is intense.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Preacher Curl','basic','Biceps','Biceps','EZ-bar or dumbbell, preacher bench','With the upper arms on the pad, curl up and lower until the arms are nearly straight.','Stop just short of snapping the elbows straight at the bottom to protect the joint.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cable Curl','basic','Biceps','Biceps','Cable machine','Facing a low pulley with a straight or EZ handle, curl to the shoulders and return slowly.','Keep the elbows at the sides and the tension constant.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Triceps Pushdown','basic','Triceps','Triceps','Cable machine','With the elbows at the sides, push the bar or rope down until the arms are straight, then return until the forearms are just past parallel.','Keep the upper arms still and do not lean over the bar.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Skull Crusher','basic','Triceps','Triceps','EZ-bar or dumbbells, bench','Lie back, lower the weight toward the forehead by bending only the elbows, then extend.','Keep the elbows pointing at the ceiling rather than flaring, and use a controlled tempo.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bench Dip','basic','Triceps','Triceps, Chest','Bench','With the hands on a bench behind you, lower the body by bending the elbows to about 90 degrees, then press up.','Keep the back close to the bench and do not sink the shoulders below elbow height.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Close-Grip Bench Press','basic','Triceps','Triceps, Chest','Barbell, bench','With the hands about shoulder-width apart, lower the bar to the lower chest with the elbows tucked, then press up.','Do not go narrower than shoulder-width, which stresses the wrists.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Triceps Kickback','basic','Triceps','Triceps','Dumbbell','Hinge forward with the upper arm parallel to the floor, extend the forearm back until the arm is straight, then return.','Keep the upper arm fixed and use light weight.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Parallel Bar Dip','basic','Triceps','Triceps, Chest, Shoulders','Dip bars','Support the body on the bars, lower until the upper arms are about parallel to the floor, then press up.','Keep the torso upright for triceps focus and stop if the shoulders feel pinched.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Reverse Curl','basic','Wrist / Forearm','Forearms, Brachioradialis','Barbell or EZ-bar','With an overhand grip, curl the bar up toward the shoulders and lower slowly.','Keep the wrists straight and the elbows at the sides; use lighter weight than a normal curl.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wrist Roller','basic','Wrist / Forearm','Forearms','Wrist roller or rope with weight','Hold the bar at arm length and roll the rope up by turning the wrists, then unroll slowly.','Keep the arms extended and use light weight; stop if the wrists ache.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Plate Pinch','basic','Wrist / Forearm','Grip, Forearms','Weight plates','Pinch two smooth-sided plates together with the fingers and thumb and hold for time.','Keep the shoulders relaxed and the grip firm; do not shrug.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dead Hang','basic','Wrist / Forearm','Grip, Forearms, Shoulders','Pull-up bar','Hang from the bar with an overhand grip and arms straight for time.','Keep the shoulders slightly engaged rather than hanging limp, and step down if the grip fails.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Donkey Calf Raise','basic','Calves','Calves','Machine or bodyweight with a partner load','Bend forward at the hips with the balls of the feet on a step, rise up as high as possible, then lower to a deep stretch.','Use the full range; do not bounce out of the bottom.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Single-Leg Calf Raise','basic','Calves','Calves','Step or bodyweight','Balance on one foot on the edge of a step, rise high onto the toes, then lower below the step level.','Hold a wall for balance and move slowly through the whole range.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Leg Press Calf Raise','basic','Calves','Calves','Leg press machine','With the balls of the feet on the lower platform edge and legs nearly straight, press the toes down and return.','Keep the knees almost straight but not locked.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Crunch','basic','Core','Abs','Bodyweight','Lie on the back with the knees bent, curl the shoulders off the floor toward the pelvis, then lower slowly.','Keep the neck neutral and the chin off the chest; the abs lift the shoulders, not the hands.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Reverse Crunch','basic','Core','Lower abs','Bodyweight','Lie on the back with the knees bent over the hips, curl the pelvis off the floor toward the ribs, then lower with control.','Use the abs to lift rather than swinging the legs.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dead Bug','basic','Core','Core, Deep abs','Bodyweight','Lie on the back with the arms up and knees bent over the hips; lower the opposite arm and leg toward the floor, then return.','Keep the lower back pressed to the floor throughout.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bird Dog','basic','Core','Core, Lower back, Glutes','Bodyweight','On hands and knees, extend the opposite arm and leg until they are in line with the torso, then return.','Keep the hips level and the spine neutral; do not arch or rotate.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Lying Leg Raise','basic','Core','Lower abs, Hip flexors','Bodyweight','Lie on the back with the legs straight, raise them to vertical and lower slowly without touching the floor.','Press the lower back into the floor; bend the knees if the back arches.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Ab Wheel Rollout','basic','Core','Abs, Core','Ab wheel','From the knees, roll the wheel forward while keeping the core braced, then pull back to the start.','Do not let the hips sag or the lower back arch; shorten the range if needed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('V-Up','basic','Core','Abs, Hip flexors','Bodyweight','Lie flat, then lift the straight legs and torso at the same time to touch the toes in a V shape, then lower.','Move with control and avoid jerking the neck.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Flutter Kicks','basic','Core','Lower abs','Bodyweight','Lie on the back with the legs lifted slightly off the floor and alternate small up-and-down kicks.','Keep the lower back pressed down and the movement small and steady.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cable Crunch','basic','Core','Abs','Cable machine, rope','Kneel below a high pulley holding the rope at the head and crunch the ribs toward the pelvis, then return.','Curl the spine rather than bending at the hips.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hollow Body Hold','basic','Core','Abs, Core','Bodyweight','Lie on the back and lift the shoulders and straight legs slightly off the floor with the arms overhead, holding the position.','Keep the lower back flat on the floor; raise the legs higher to make it easier.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Dumbbell Side Bend','basic','Obliques','Obliques','Dumbbell','Standing with a dumbbell in one hand, bend sideways toward the weight and return upright.','Keep the movement in the side only, without leaning forward or back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Heel Touches','basic','Obliques','Obliques','Bodyweight','Lie on the back with the knees bent and reach each hand toward the same-side heel by crunching sideways.','Keep the shoulders slightly lifted and move side to side with control.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Windshield Wipers','basic','Obliques','Obliques, Lower abs','Bodyweight','Lie on the back with the legs lifted straight up and slowly lower them side to side like wipers.','Keep the shoulders on the floor and reduce the range if the lower back arches.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Plank Hip Dips','basic','Obliques','Obliques, Core','Bodyweight','In a forearm plank, rotate the hips to lower one side toward the floor, then the other.','Keep the shoulders stable and the movement controlled.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Jump Rope','basic','Cardio','Full body, Calves','Jump rope','Turn the rope with the wrists and hop lightly on the balls of the feet, staying low to the ground.','Land softly and keep the elbows close to the ribs.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Butt Kicks','basic','Cardio','Hamstrings, Cardio','Bodyweight','Jog in place, flicking the heels up toward the glutes on each step.','Stay tall and keep the knees pointing down.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Lateral Shuffle','basic','Cardio','Legs, Cardio','Bodyweight','In a low athletic stance, shuffle sideways several steps and back without crossing the feet.','Stay low with the chest up and the toes forward.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Shadow Boxing','basic','Cardio','Full body, Cardio','Bodyweight','In a light stance, throw straight punches, hooks, and slips in continuous combinations.','Keep the guard up and the knees soft, rotating from the hips.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Stationary Bike','basic','Cardio','Legs, Cardio','Stationary bike','Pedal at a steady pace with the seat set so the knee is slightly bent at the bottom of the stroke.','Keep the back straight and the shoulders relaxed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Rowing Machine','basic','Cardio','Full body, Cardio','Rowing machine','Push with the legs first, then lean back and pull the handle to the ribs, then reverse the sequence.','Do not pull with the arms first; the drive comes from the legs.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Treadmill Brisk Walk','basic','Cardio','Legs, Cardio','Treadmill','Walk briskly at a steady incline or pace that raises the heart rate but still lets you talk.','Keep the posture tall and avoid holding the handrails for balance.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Tuck Jump','basic','Cardio','Full body, Power','Bodyweight','From a quarter squat, jump up and bring the knees toward the chest, then land softly.','Land softly with bent knees and stop if the landings become heavy.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Arm Circles','basic','Mobility & Stretching','Shoulders','Bodyweight','Extend the arms to the sides and draw small then larger circles forward and backward.','Keep the shoulders relaxed and the neck long.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hip Circles','basic','Mobility & Stretching','Hips','Bodyweight','Standing on one leg with support, lift the other knee and draw slow circles at the hip in both directions.','Keep the torso still and the movement smooth.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('90/90 Hip Switch','basic','Mobility & Stretching','Hips','Bodyweight','Sit with both knees bent to 90 degrees on the floor and rotate the knees from one side to the other.','Keep the torso tall and move gently within a comfortable range.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Quad Stretch','basic','Mobility & Stretching','Quads','Bodyweight','Standing, pull one heel toward the glute and keep the knees together, holding the stretch.','Keep the hips square and avoid arching the lower back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Butterfly Stretch','basic','Mobility & Stretching','Inner thighs, Hips','Bodyweight','Sit with the soles of the feet together and gently let the knees drop toward the floor.','Sit tall and do not bounce the knees.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Triceps Overhead Stretch','basic','Mobility & Stretching','Triceps, Shoulders','Bodyweight','Raise one arm overhead, bend the elbow so the hand drops behind the head, and gently press the elbow with the other hand.','Keep the ribs down and do not force the elbow.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Cross-Body Shoulder Stretch','basic','Mobility & Stretching','Rear shoulder','Bodyweight','Bring one arm across the chest and hold it with the other arm.','Keep the shoulders down and away from the ears.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Calf Stretch','basic','Mobility & Stretching','Calves','Wall','Place the hands on a wall, step one leg back with the heel down and lean forward until the calf stretches.','Keep the back heel on the floor and the back leg straight.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Forward Fold','basic','Mobility & Stretching','Hamstrings, Lower back','Bodyweight','Sit with the legs extended and hinge forward from the hips toward the toes.','Lead with the chest and stop where a mild stretch is felt, without rounding hard.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Knee-to-Chest Stretch','basic','Mobility & Stretching','Lower back, Glutes','Bodyweight','Lie on the back and hug one knee toward the chest, holding the stretch.','Keep the head down and the other leg relaxed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wrist Flexor Stretch','basic','Mobility & Stretching','Forearms, Wrist','Bodyweight','Extend one arm forward with the palm up and gently pull the fingers back with the other hand.','Keep the elbow straight and stretch gently, without forcing.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Figure-Four Glute Stretch','basic','Mobility & Stretching','Glutes, Hips','Bodyweight','Lying on the back, cross one ankle over the opposite knee and pull the thigh toward the chest.','Keep the head down and the hips level.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Overhead Side Reach','basic','Mobility & Stretching','Lats, Obliques','Bodyweight','Standing, raise one arm overhead and lean sideways, feeling the stretch along the side of the body.','Keep both feet planted and avoid twisting forward.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Neck Side Stretch','basic','Mobility & Stretching','Neck, Upper traps','Bodyweight','Tilt the ear toward the shoulder and hold gently, then switch sides.','Keep the opposite shoulder low and avoid pulling hard with the hand.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Mountain Pose (Tadasana)','basic','Yoga & Meditation','Posture, Full body','Yoga mat','Stand tall with the feet together, weight even, arms at the sides, and breathe steadily.','Lengthen the spine and relax the shoulders down and back.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Tree Pose (Vrksasana)','basic','Yoga & Meditation','Balance, Hips','Yoga mat','Stand on one leg with the other foot on the inner calf or thigh, never the knee, and hands together at the chest.','Fix the eyes on a still point and press the foot and leg firmly into each other.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Warrior I Pose','basic','Yoga & Meditation','Legs, Hips, Shoulders','Yoga mat','Step one foot back, bend the front knee over the ankle and raise the arms overhead with the hips facing forward.','Keep the front knee over the ankle and the back heel grounded.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Triangle Pose (Trikonasana)','basic','Yoga & Meditation','Hamstrings, Sides, Hips','Yoga mat','With a wide stance, hinge sideways over the front leg and extend the arms in one line, one toward the floor and one to the ceiling.','Keep the chest open and both legs straight without locking the knees.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bridge Pose','basic','Yoga & Meditation','Glutes, Spine','Yoga mat','Lie on the back with the knees bent, lift the hips up and hold, keeping the knees over the ankles.','Keep the neck relaxed and press evenly through both feet.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Chair Pose (Utkatasana)','basic','Yoga & Meditation','Quads, Glutes, Core','Yoga mat','Bend the knees as if sitting back into a chair with the arms raised overhead, and hold.','Keep the weight in the heels and the chest lifted.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Pigeon Pose','basic','Yoga & Meditation','Hips, Glutes','Yoga mat','From all fours, bring one shin forward across the mat and extend the other leg back, folding gently over the front leg.','Support the hips with a cushion if needed and stop at any knee discomfort.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Spinal Twist','basic','Yoga & Meditation','Spine, Hips','Yoga mat','Sit tall and twist toward the bent knee, using the opposite hand for gentle leverage.','Grow tall with each inhale and twist a little more on each exhale, without forcing.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Happy Baby Pose','basic','Yoga & Meditation','Hips, Lower back','Yoga mat','Lie on the back, hold the outer feet with the knees bent toward the armpits, and rock gently.','Keep the tailbone and head down and the shoulders relaxed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Legs-Up-the-Wall','basic','Yoga & Meditation','Legs, Nervous system','Wall, yoga mat','Lie on the back with the hips near a wall and the legs resting up the wall, staying relaxed.','Move the hips closer or farther from the wall until the position feels comfortable.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Corpse Pose (Savasana)','basic','Yoga & Meditation','Full body relaxation','Yoga mat','Lie flat on the back with the arms relaxed at the sides and the eyes closed, letting the body go still.','Release effort in every muscle and let the breath be natural.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Mindfulness Breath Meditation','basic','Yoga & Meditation','Mind, Nervous system','None','Sit comfortably and rest attention on the natural breath, gently returning to it whenever the mind wanders.','There is no need to stop thoughts; simply notice them and return to the breath without judgment.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Alternate Nostril Breathing','basic','Yoga & Meditation','Nervous system','None','Sit tall, close one nostril and inhale through the other, then switch and exhale, alternating slowly.','Keep the breath smooth and quiet and stop if you feel light-headed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Sit-to-Stand','basic','Seniors','Legs, Glutes','Chair','From a sturdy chair, stand up without using the hands if possible, then sit back down with control.','Place the feet hip-width apart and lean slightly forward as you rise; use the arms for help if needed.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Single-Leg Stand','basic','Seniors','Balance, Legs','Chair or wall for support','Hold onto support and lift one foot slightly off the floor, holding the balance.','Stand tall and look ahead; keep a hand on the support for safety.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Heel-to-Toe Walk','basic','Seniors','Balance, Legs','Open floor near a wall','Walk in a straight line placing the heel of one foot directly in front of the toes of the other.','Walk beside a wall or counter for safety and keep the eyes ahead.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Leg Extension','basic','Seniors','Quads','Chair','Seated, straighten one knee to lift the foot up, hold briefly, and lower slowly.','Sit tall against the back of the chair and avoid locking the knee hard.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Band Row','basic','Seniors','Upper back, Biceps','Resistance band, chair','Sit tall with a band around the feet or a fixed point, pull the handles back and squeeze the shoulder blades, then release.','Keep the shoulders down and the back straight.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Seated Arm Raise','basic','Seniors','Shoulders','Chair, light weights optional','Seated tall, raise the arms forward and up to shoulder height and lower slowly.','Keep the shoulders relaxed and use light or no weight.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Wall Angel','basic','Seniors','Shoulders, Upper back, Posture','Wall','Stand with the back near a wall and slide the arms up and down in a W to Y shape, keeping contact with the wall where comfortable.','Keep the ribs down and stay within a pain-free range.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Standing Hip Extension','basic','Seniors','Glutes, Balance','Chair or wall for support','Holding a support, move one straight leg backward with control and return.','Keep the torso upright and do not lean forward.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Frog Jump','basic','Children','Legs, Coordination','Bodyweight','From a low squat with the hands on the floor, jump forward like a frog and land softly.','Encourage soft landings with bent knees, on a safe non-slip surface.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Crab Walk','basic','Children','Shoulders, Core, Legs','Bodyweight','Sit with the hands behind and lift the hips, then walk forward or backward on the hands and feet.','Keep the hips lifted and go slowly on a clear surface.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Duck Walk','basic','Children','Legs, Balance','Bodyweight','Walk forward in a deep squat with the hands behind the back or at the sides like wings.','Keep the chest up and stay within a comfortable depth.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Line Balance Walk','basic','Children','Balance, Coordination','Floor line or tape','Walk heel to toe along a line, keeping the arms out for balance.','Look ahead rather than down and go slowly.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Hopscotch Jumps','basic','Children','Legs, Coordination','Floor markings','Hop and jump through a hopscotch pattern, landing on one or two feet.','Land softly and keep the play area clear.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Skipping','basic','Children','Cardio, Coordination','Bodyweight','Skip forward with alternating steps and hops, swinging the arms naturally.','Keep it light and rhythmic.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Bunny Hop','basic','Children','Legs, Coordination','Bodyweight','Jump forward with both feet together, landing softly and rebounding into the next hop.','Land softly with bent knees.') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_exercises (name, tier, category, muscle_group, equipment, instructions, posture_tips) VALUES ('Airplane Balance','basic','Children','Balance, Back, Glutes','Bodyweight','Stand on one leg, lean forward and extend the other leg back with the arms out like wings.','Hold near a wall or a helper at first and go only as far as balance allows.') ON CONFLICT (lower(name)) DO NOTHING;
