INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by) VALUES ('Meditation & Breathing — Daily Practice','Yoga & Meditation',NULL,'All levels','A calming daily routine for focus and stress control.',public._tx_list('Diaphragmatic Breathing|1|5 min|0|Bodyweight|;Box Breathing|1|5 min|0|Bodyweight|;Alternate Nostril Breathing|1|5 min|0|Bodyweight|;Guided Body Scan|1|10 min|0|Bodyweight|;Mindfulness Breath Meditation|1|10 min|0|Bodyweight|;Corpse Pose (Savasana)|1|5 min|0|Bodyweight|'),'seed') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by) VALUES ('Seniors — Low Impact Full Body','Seniors',NULL,'All levels','Chair-supported, low-impact strength. Stop if you feel dizzy, and check with a doctor before starting if you have any health conditions.',public._tx_list('Sit-to-Stand|2|12|60|Bodyweight|;Wall Push-Up|2|12|60|Bodyweight|;Seated Band Row|2|12|60|Maintain|Light;Seated Arm Raise|2|12|45|Bodyweight|;Seated Marching|2|20|45|Bodyweight|;Diaphragmatic Breathing|1|3 min|0|Bodyweight|'),'seed') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by) VALUES ('Seniors — Balance & Mobility','Seniors',NULL,'All levels','Balance, hip and leg work. Always keep a wall or chair within reach.',public._tx_list('Single-Leg Stand|2|20 sec|45|Bodyweight|;Heel-to-Toe Walk|2|10 steps|45|Bodyweight|;Standing Hip Extension|2|12|45|Bodyweight|;Standing Side Leg Raise|2|12|45|Bodyweight|;Seated Leg Extension|2|12|45|Bodyweight|;Wall Angel|2|12|45|Bodyweight|'),'seed') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by) VALUES ('Children — Fun Fitness Basics','Children',NULL,'Beginner','Play-based movement for children about 6-12 years old. Always supervise and keep the play area clear.',public._tx_list('Jumping Jacks|2|12|30|Bodyweight|;Bunny Hop|2|12|30|Bodyweight|;Bodyweight Squat|2|12|30|Bodyweight|;Wall Push-Up|2|12|30|Bodyweight|;Bear Crawl|2|20 sec|30|Bodyweight|;Plank|2|15 sec|30|Bodyweight|'),'seed') ON CONFLICT (lower(name)) DO NOTHING;
INSERT INTO public.workout_day_templates (name, split_family, day_position, level, description, exercises, created_by) VALUES ('Children — Animal Walks & Balance','Children',NULL,'Beginner','Coordination and balance games. Always supervise and use a non-slip surface.',public._tx_list('Frog Jump|2|12|30|Bodyweight|;Crab Walk|2|20 sec|30|Bodyweight|;Duck Walk|2|20 sec|30|Bodyweight|;Line Balance Walk|2|10 steps|30|Bodyweight|;Hopscotch Jumps|2|12|30|Bodyweight|;Airplane Balance|2|10 sec|30|Bodyweight|'),'seed') ON CONFLICT (lower(name)) DO NOTHING;

-- ── Ready-to-assign plans built from the templates ────────────────────
INSERT INTO public.workout_plans (name, tier, description, structure, created_by)
SELECT '3-Day Full Body Plan — Beginner (Weekly)', 'basic', 'Three full-body days per week with rest days between.',
  (SELECT jsonb_agg(jsonb_build_object('day_number', d.n, 'day_label', regexp_replace(d.name, '^.* — ', ''), 'exercises', d.exercises) ORDER BY d.n)
   FROM (SELECT array_position(ARRAY['3-Day Full Body Split — Day 1: Full Body A','3-Day Full Body Split — Day 2: Full Body B','3-Day Full Body Split — Day 3: Full Body C'], t.name) AS n, t.name, t.exercises FROM public.workout_day_templates t WHERE t.name = ANY(ARRAY['3-Day Full Body Split — Day 1: Full Body A','3-Day Full Body Split — Day 2: Full Body B','3-Day Full Body Split — Day 3: Full Body C'])) d),
  'seed'
WHERE NOT EXISTS (SELECT 1 FROM public.workout_plans WHERE lower(name) = lower('3-Day Full Body Plan — Beginner (Weekly)'));
