   FROM (SELECT array_position(ARRAY['Yoga Flow — Intermediate'], t.name) AS n, t.name, t.exercises FROM public.workout_day_templates t WHERE t.name = ANY(ARRAY['Yoga Flow — Intermediate'])) d),
  'seed'
WHERE NOT EXISTS (SELECT 1 FROM public.workout_plans WHERE lower(name) = lower('Yoga Flow — Intermediate (1-day plan)'));
